func storageReadWriteCloser(count int, compress bool, encryptor *encryption.Encryptor) ([]io.Reader, io.Writer, io.Closer) {
	var prs []io.Reader
	var pws []io.Writer
	var pcs []io.Closer
	for i := 0; i < count; i++ {
		pr, pw := io.Pipe()

		prs = append(prs, pr)

		var w io.Writer = pw
		// Closers are collected from the innermost (closest to the pipe) to the outermost writer
		// and appended in reverse below, so the outer writers flush before the inner ones are closed.
		closers := []io.Closer{pw}

